import express from 'express';
const app = express();
app.get('/api/users/:id', (req, res) => {
  const id = req.params.id;
  if (!/^\d+$/.test(id)) return res.status(400).json({ error: 'Invalid id' });
  res.json({ id: Number(id) });
});
app.listen(3000);

